"""Render ../COPY.md from the ROWS of build_copy.py (the CopyTable board source)."""
import os
from build_copy import ROWS

OWNER = {
    'Banner': 'S5b', 'Key menu': 'S16b', 'Typing time': 'S16b', 'Typing ran out': 'S16b',
}


def owner(area):
    for k, v in OWNER.items():
        if area.startswith(k):
            return v
    return 'Copy PR'


def cell(s):
    return (s or '').replace('|', '\\|').replace('\n', ' ') or '-'


def main():
    out = ['# Copy table', '',
           'Generated by `design/work/copy_md.py` from the `ROWS` of `design/work/build_copy.py`; the board is `design/CopyTable.dc.html` (render: `design/refs/CopyTable.png`). Approved by the operator on 2026-11-11.', '',
           '- `●` marks a row that changes: the Proposed column is what to implement. Rows marked `keep` stay as they are.',
           '- `desk-1` stands for the computer\'s Tailscale machine name from the serve identity (fallback: hostname). `/` separates a title line from the second line. Square brackets are buttons.',
           '- Owner: **S5b** pairing screen and banners, **S16b** special keys menu and typing-time lines, **Copy PR** every other changed row.',
           '', '| | Area | Where | Current | Proposed | Owner | Source |', '|---|---|---|---|---|---|---|']
    for area, where, cur, prop, src in ROWS:
        keep = prop.startswith('keep')
        out.append(f'| {"" if keep else "●"} | {cell(area)} | `{where}` | {cell(cur)} | {cell(prop)} | {"-" if keep else owner(area)} | {cell(src)} |')
    open(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'COPY.md'), 'w').write('\n'.join(out) + '\n')


if __name__ == '__main__':
    main()
